// AD4-KEY-CHECK
// THE KEY IS NOT IN THIS FILE ANY MORE, AND THAT IS THE POINT.
//
// Every Supabase node in this workflow authenticates with an n8n SUPABASE
// CREDENTIAL rather than a key pasted into the Config node. That is one place
// to set it instead of twelve, it is encrypted at rest in n8n, and exporting
// this workflow can no longer leak it - the old shape had the service key
// sitting in plain text inside a JSON file that gets emailed around.
//
// SET IT UP ONCE, BEFORE IMPORTING ANYTHING:
//   n8n -> Credentials -> New -> Supabase API
//     Name         AD4 Supabase        <- this name exactly
//     Host         https://<your-project-ref>.supabase.co
//     Service Role the SERVICE ROLE key (Project Settings -> API keys)
//
// The name matters because every Supabase node in every AD4 workflow is
// already bound to a credential called AD4 Supabase. Create it first and
// n8n links all of them on import - nothing to pick node by node. Import
// first and the nodes come in unbound, and you pick the credential on each
// one by hand; it works, it is just ~57 dropdowns instead of zero.
//
// The credential sends `apikey` and `Authorization: Bearer` itself, which is
// exactly what these nodes used to set by hand.
//
// WHAT STILL CHECKS THE KEY. This node can no longer read it - a credential
// is not visible to an expression, by design. Two things downstream do:
//
//   the schedule gate, immediately below. sql/ad4_38 revokes should_run from
//   anon, so a credential holding the publishable key is refused HERE, two
//   nodes in, before a single row is fetched.
//
//   the write guard in the Summary node, which names any refusal the
//   database gives and refuses to report success on a run that wrote nothing.
//
// supabase_url stays in Config because an expression has to build the request
// URL and cannot read the credential's host. It is not a secret.
{
  const cfg = $('Config').first().json ?? {};
  const url = String(cfg.supabase_url ?? '').trim();
  if (!url) {
    throw new Error(
      'Config -> supabase_url is empty. Set it to exactly ' +
      'https://<your-project-ref>.supabase.co - no trailing slash and no /rest/v1, ' +
      'which every node below appends itself. The KEY does not go here: it belongs in ' +
      'the n8n Supabase credential (Credentials -> New -> Supabase API), which is ' +
      'where the nodes now read it from.');
  }
  if (!/^https:\/\//.test(url) || /\/rest\b/.test(url) || /\/$/.test(url)) {
    throw new Error(
      `Config -> supabase_url is "${url}", which is not the shape every node below ` +
      'expects: https://<your-project-ref>.supabase.co, no trailing slash, no /rest/v1. ' +
      'Nothing was fetched and nothing was written.');
  }
}

// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the saving
// is here: returning no items stops every node below, and the execution ends
// having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql) and
// the Workflows page edits it. A manual or webhook run always proceeds - a Run
// button that obeyed the cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A PERMISSION ERROR IS NOT AN UNAVAILABLE GATE. 42501 here means the key
// cannot even call should_run, and a key that cannot do that cannot write
// either - so stop, rather than failing open into a run that writes nothing.
//
// THIS NODE CANNOT CHECK THE KEY ITSELF ANY MORE - it is in the credential,
// which an expression cannot read. So a refusal here is one of two things and
// both stop the run: the credential holds the anon/publishable key rather than
// the service role key, or service_role has not been granted what it needs.
// Either way every write below would be refused the same way, so there is
// nothing to gain by going on. ad4_38's output tells you which it was.
//
// ad4_38 revokes should_run from anon for this reason: it was granted so the
// Workflows page could preview a cadence, that page reads v_execution_budget
// instead, and the grant only let a bad key through the gate.
if (decision && (String(decision.code) === '42501' ||
                 /permission denied/i.test(String(decision.message || '')))) {
  throw new Error(
    `Supabase refused should_run: ${decision.message} (${decision.code}). Every write below ` +
    `would be refused the same way, so nothing was fetched and nothing was written. Two ` +
    `things cause this and the workflow cannot tell them apart, because the key now lives ` +
    `in the n8n credential where an expression cannot read it. (1) THE KEY: open n8n -> ` +
    `Credentials -> the Supabase account these nodes use and check Service Role Secret ` +
    `holds the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or a ` +
    `key beginning sb_secret_) - an anon key gets exactly this error, because anon is ` +
    `granted SELECT and nothing else. NEVER put the service key anywhere starting ` +
    `NEXT_PUBLIC_. (2) THE DATABASE: service_role has not been granted what it needs. Run ` +
    `sql/ad4_38_grants.sql in the Supabase SQL editor - it grants the write path back and ` +
    `then prints one row per ingest table saying whether the service key can write it, ` +
    `which also tells you which of the two it was.`);
}

// A gate that fails closed would silently disable every workflow the first
// time the settings row is missing or the RPC is absent. Fail OPEN: an
// unreachable gate means run, and say so in the log.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  // Recorded, so a skipped run is visible on the Workflows page as a skip
  // rather than looking like a workflow that silently stopped working.
  return [{ json: { __skipped: true, reason: decision.reason || 'not scheduled',
                    minutes_since: decision.minutes_since ?? null,
                    every_minutes: decision.every_minutes ?? null } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node
// is skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;

// ONE REQUEST FOR THE WHOLE BOARD.
//
// This node used to emit one item per station and the Fetch node sent 48
// requests. That is why this workflow could not be scheduled: n8n Cloud
// shares one egress IP and IEM rate-limits by IP. Measured against the live
// service from this very instance:
//
//     12 concurrent   44 of 48 stations returned nothing
//      4 concurrent   42 of 48
//      1 at a time    34 of 48, in 26 s - most rejected before being served
//     every failure body: "Too many requests from your IP address, slow down."
//
// Serialising did not help, which is the diagnosis: the limiter counts
// REQUESTS per IP, not connections. The ASOS service accepts repeated
// station= parameters, so the fix is to stop making 48 requests. Measured
// from the same egress on 2026-09-22:
//
//     one request, all 48 stations   48 of 48 returned, 2,239 rows, 138 KB,
//                                    ~4 s, no rate limit at all
//     the same 48 over the last 4h   168 rows, 10 KB
//
// sts/ets bound the window to an INSTANT rather than a whole day, which is
// what makes an hourly cadence cheap. The day parameters go too because the
// service wants a window either way and they are harmless once sts/ets are
// present - measured byte-identical with and without them.
//
// BUILT BY HAND, NOT WITH URLSearchParams. n8n's Code node sandbox does not
// expose it, and a plain `node` does - so an earlier version ran green in the
// repo's test harness and died on its first real execution with
// `URLSearchParams is not defined [line 34]`.
const cfg = $('Config').first().json;
const cities = $('Load cities').all().map(i => i.json).flat();
const hoursBack = Number(cfg.hours_back || 6) || 6;
const cap = Number(cfg.max_cities_per_run || 0) || 0;

// Same scope contract every other AD4 workflow honours: absent, "all", or a
// selection matching nothing all mean every active city, because a scope that
// silently reduces a run to zero is indistinguishable from a broken job.
const _scope = (($('Check schedule').first().json ?? {}).scope) ?? {};
const _only = Array.isArray(_scope.cities) && _scope.cities.length
  ? new Set(_scope.cities) : null;

// IEM ANSWERS A US STATION UNDER ITS THREE-LETTER ID. Ask for KAUS, get rows
// labelled AUS. Invisible while each request carries one station, because the
// caller already knows what it asked for - fatal the moment one response
// carries all of them: a map keyed on cities.icao alone drops every US city,
// 11 of 48 here, including New York, Chicago, Los Angeles and Miami.
const byStation = {};
const stations = [];
const clash = [];
for (const c of cities) {
  if (!c || !c.city_key || !c.icao) continue;
  if (_only && !_only.has(c.city_key)) continue;
  if (cap && stations.length >= cap) break;
  const icao = String(c.icao).trim().toUpperCase();
  if (!icao) continue;
  stations.push(icao);
  const aliases = [icao];
  if (icao.length === 4 && icao[0] === 'K') aliases.push(icao.slice(1));
  for (const a of aliases) {
    if (byStation[a] !== undefined && byStation[a] !== c.city_key) {
      clash.push(a + ': ' + byStation[a] + ' and ' + c.city_key);
      continue;
    }
    byStation[a] = c.city_key;
  }
}
if (clash.length) {
  // Refused, not resolved. Putting one city's afternoon on another city's
  // market is worse than a station nobody claims.
  throw new Error('two cities answer to the same IEM station id: ' + clash.join('; '));
}
if (!stations.length) {
  throw new Error('no active city carries an ICAO - nothing to ask IEM for');
}

const now = new Date();
const since = new Date(now.getTime() - hoursBack * 3600 * 1000);
const iso = (d) => d.toISOString().slice(0, 16) + 'Z';
// day2 ON THE ASOS SERVICE IS EXCLUSIVE. Asking for [start, today) returns
// every day but the one being traded, and the damage self-heals overnight,
// which is why it survived three weeks of checks.
const d1 = new Date(Date.UTC(since.getUTCFullYear(), since.getUTCMonth(), since.getUTCDate()));
const d2 = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1));

const q = [];
for (const s of stations) q.push(['station', s]);
// mslp, NOT alti or a raw station pressure. Sea-level pressure is the only one
// comparable across a board running from Singapore at 5 m to Mexico City at
// 2,240 m, where station pressure is ~770 hPa on the calmest day of the year.
q.push(['data', 'tmpf,dwpf,relh,drct,sknt,p01i,skyc1,mslp']);
q.push(['year1', d1.getUTCFullYear()], ['month1', d1.getUTCMonth() + 1], ['day1', d1.getUTCDate()]);
q.push(['year2', d2.getUTCFullYear()], ['month2', d2.getUTCMonth() + 1], ['day2', d2.getUTCDate()]);
q.push(['sts', iso(since)], ['ets', iso(now)]);
q.push(['tz', 'Etc/UTC'], ['format', 'onlycomma'], ['latlon', 'no']);
// ROUTINE AND SPECIAL REPORTS (plan v2 P2.1): report_type=3 alone is one
// report an hour, so half-hourly stations lost half the day and every
// special was dropped. Measured 23 Sep against the venue's WRH maxima:
// EGLC 17 Sep 21C -> 22C (WRH 22), EHAM 12 Sep 21C -> 22C (WRH 22),
// LGA 20 Sep 71F -> 72F (WRH 72), DAL 13 Sep 99F both (WRH 99).
q.push(['missing', 'empty'], ['trace', 'empty'], ['direct', 'no'], ['report_type', '3'], ['report_type', '4']);
const url = 'https://mesonet.agron.iastate.edu/cgi-bin/request/asos.py?' + q.map(
  (pr) => encodeURIComponent(pr[0]) + '=' + encodeURIComponent(String(pr[1]))).join('&');

return [{ json: {
  url,
  stations,
  by_station: byStation,
  requested: stations.length,
  hours_back: hoursBack,
  since: iso(since),
  until: iso(now),
} }];

// Parse IEM's CSV into weather_observations rows. Ported from
// scripts/ingest_observations.parse(), which stays the backfill path.
//
// ONE RESPONSE, MANY STATIONS. Every row is attributed by its OWN station
// column against the map Build requests made - never by position, and never
// by "whichever city we were last looking at". A row whose station is not in
// the map is dropped and named: an unrecognised id is either a city we did
// not ask for or the K-prefix trap, and guessing would file one city's
// afternoon under another city's market.
const req = $('Build requests').first().json;
const byStation = req.by_station || {};
// The response, or whatever n8n could tell us instead. With retries
// exhausted the item arrives as {error: ...} rather than {csv: ...}, and a
// run that says "nothing parsed" without saying why is the failure this
// workflow exists to stop.
const fetched = $('Fetch observations').first().json || {};
const body = String(
  fetched.csv
  ?? (fetched.error && (fetched.error.message || fetched.error.description))
  ?? fetched.message
  ?? '');

const num = (x) => {
  if (x === undefined || x === null || x === '') return null;
  const v = Number(x);
  return Number.isFinite(v) ? v : null;
};
const fToC = (v) => v === null ? null : Math.round((v - 32) * 5 / 9 * 100) / 100;

// METAR sky-cover is a CODE, not a number, and weather_observations.cloud_cover
// is numeric - writing the raw code through is what made every observations run
// die with `invalid input syntax for type numeric: "FEW"`. Oktas is the standard
// numeric form of this measurement, so the conversion loses nothing.
const SKY = { SKC:0, CLR:0, NSC:0, NCD:0, CAVOK:0, FEW:2, SCT:4, BKN:6, OVC:8, VV:8 };
const oktas = (codeRaw) => {
  const c = String(codeRaw || '').trim().toUpperCase();
  if (!c) return null;
  if (c in SKY) return SKY[c];
  for (const k of Object.keys(SKY)) if (c.startsWith(k)) return SKY[k];  // e.g. BKN035
  return null;
};

// WHAT IEM ACTUALLY SAID when nothing usable came back. Without this a rate
// limit, an outage and a quiet hour are the same number in the log.
const rateLimited = body.toLowerCase().indexOf('too many requests') >= 0;

const lines = body.split('\n');
const header = (lines[0] || '').split(',').map((h) => h.trim());
const idx = {};
header.forEach((h, i) => { idx[h] = i; });

const rows = [];
const seen = {};
const unknown = {};
for (let i = 1; i < lines.length; i++) {
  const line = lines[i];
  if (!line || !line.trim()) continue;
  const f = line.split(',');
  const station = String(f[idx['station']] || '').trim().toUpperCase();
  if (!station) continue;
  const cityKey = byStation[station];
  if (cityKey === undefined) { unknown[station] = (unknown[station] || 0) + 1; continue; }

  const ts = String(f[idx['valid']] || '').trim();
  if (ts.length < 16) continue;
  const validAt = ts.slice(0, 10) + 'T' + ts.slice(11, 16) + ':00Z';
  const tmpf = num(f[idx['tmpf']]);
  if (tmpf === null) continue;

  seen[cityKey] = (seen[cityKey] || 0) + 1;
  rows.push({
    city_key: cityKey,
    station: station,
    valid_at: validAt,
    temp_f: tmpf,
    temp_c: fToC(tmpf),
    dewpoint_c: fToC(num(f[idx['dwpf']])),
    humidity: num(f[idx['relh']]),
    wind_speed: num(f[idx['sknt']]),
    wind_dir_deg: num(f[idx['drct']]),
    precip: num(f[idx['p01i']]),
    cloud_cover: oktas(f[idx['skyc1']]),
    // PRESSURE WAS NEVER COLLECTED until 2026-09-21: 0 of 142,529 observations
    // carried one, while derived_city_day_features had been reading
    // morning_pressure_hpa and pressure_change_24h_hpa the whole time.
    pressure_hpa: num(f[idx['mslp']]),
    source: 'IEM',
  });
}

const asked = req.stations || [];
const silent = asked.filter((s) => {
  const city = byStation[s];
  return city === undefined || !seen[city];
});

// CHUNKED, because one POST of every station's window is a body Supabase
// refuses outright - and a refused write walks past a continue-on-error node
// looking healthy. Every chunk carries the run's totals so Summary can read
// first() and still see the whole run.
const CHUNK = 500;
const totals = {
  n_obs: rows.length,
  requested: asked.length,
  cities_with_rows: Object.keys(seen).length,
  silent_stations: silent,
  unknown_stations: Object.keys(unknown),
  rate_limited: rateLimited,
  window: { since: req.since, until: req.until, hours_back: req.hours_back },
  first_failure_body: rows.length ? null : body.slice(0, 300),
};
const out = [];
for (let i = 0; i < rows.length; i += CHUNK) {
  out.push({ json: { observations: rows.slice(i, i + CHUNK), ...totals } });
}
if (!out.length) out.push({ json: { observations: [], ...totals } });
return out;

// A run that parsed nothing must be loud. Every station empty at once is an
// IEM outage, a rate limit or a changed response shape, and "ok, 0 rows" for
// a week is how that gets missed - which is exactly what a six-hourly Actions
// cron did here.
//
// A QUIET HOUR IS NOT AN OUTAGE, though, and this workflow now runs hourly
// over a few hours rather than daily over two days. Some stations report
// every hour and some every three, so a short window legitimately returns
// fewer stations than it asked for. Nothing at all is still a fault.
const p = $input.first().json;
if (!p.observations || !p.observations.length) {
  throw new Error(
    (p.rate_limited
      ? 'IEM rate-limited this request ("Too many requests from your IP address") - '
      : 'IEM returned nothing usable for any of ' + p.requested + ' station(s) ') +
    'over ' + (p.window ? p.window.since + '..' + p.window.until : 'the window') +
    (p.first_failure_body ? ' | body: ' + p.first_failure_body : '') +
    '. Nothing was written.');
}
if (p.unknown_stations && p.unknown_stations.length) {
  // Not fatal - the rows were dropped, not misfiled - but it means the
  // station map and what IEM answers have drifted apart.
  console.log('unrecognised station id(s) dropped: ' + p.unknown_stations.join(', '));
}
return $input.all();

// DID THE DATABASE ACTUALLY TAKE IT?
//
// "Write observations" carries neverError so a refusal arrives as the PostgREST
// body instead of an exception - readable, and therefore nameable. The cost of
// that is a refused write walks past it looking healthy, which is how a job
// reports "ok, 0 rows" for a week while the data quietly stops moving.
//
// P1.2 reconstructs this across four write nodes and needs a hundred lines to
// do it. There is ONE write here, so the error is simply read off it.
let refusal = null;
for (const item of $('Write observations').all()) {
  const j = item.json || {};
  if (j.code || j.message) { refusal = j; break; }
  // A Supabase gateway timeout arrives as {"data":"upstream request timeout"}
  // with no code and no message, and was skipped entirely when this only
  // looked for those two keys.
  if (typeof j.data === 'string' && /timeout/i.test(j.data)) {
    refusal = { message: j.data, code: '504' }; break;
  }
}
if (refusal) {
  const code = String(refusal.code ?? '');
  if (code === '42501' || /permission denied/i.test(refusal.message || '')) {
    throw new Error(
      `Supabase REFUSED the write: ${refusal.message} (${code}). The key was already ` +
      `checked at "Run now?", so this is the database side: service_role has no INSERT ` +
      `on weather_observations. Run sql/ad4_38_grants.sql. Nothing was written.`);
  }
  if (code === '42P01') {
    throw new Error(
      `Supabase has no weather_observations table: ${refusal.message}. The sql/ files ` +
      `that create it have not been run. Nothing was written.`);
  }
  throw new Error(
    `Supabase refused the write: ${refusal.message}` + (code ? ` (${code})` : '') +
    (refusal.details ? ` - ${refusal.details}` : '') +
    (refusal.hint ? ` Hint: ${refusal.hint}` : '') + ' Nothing was written.');
}

const p = $('Build rows').first().json;
const rows = p.n_obs || 0;
const silent = p.silent_stations || [];
const asked = p.requested || 0;
const got = p.cities_with_rows || 0;

// A SHORT WINDOW LEGITIMATELY MISSES STATIONS. This ran daily over two days,
// where every station reports and any silence is a fault. It now runs hourly
// over a few hours, and METAR cadence is hourly at some stations and
// three-hourly at others - so naming every quiet station a failure would
// paint a healthy run 'partial' every hour and make the word useless.
//
// The bar is proportional instead: fewer than half the cities answering over
// a multi-hour window is an outage or a rate limit, not a quiet hour. The
// silent list travels either way, so a station that goes quiet for good is
// still visible in the log rather than merely absent.
const status = rows === 0 ? 'attention' : (got * 2 < asked ? 'partial' : 'ok');
const summary =
  `AD4 P1.6: ${rows} IEM observations across ${got} of ${asked} city/cities` +
  ` over ${p.window ? p.window.hours_back + 'h' : 'the window'}` +
  (silent.length ? `, ${silent.length} station(s) quiet` : '') + '.';
const detail = { stations: asked, cities_with_rows: got,
                 silent_stations: silent,
                 unknown_stations: p.unknown_stations || [],
                 rate_limited: !!p.rate_limited,
                 window: p.window,
                 first_failure_body: p.first_failure_body };
return [{ json: {
  summary, status, rows,
  log: { p_job: 'P1.6_iem_observations', p_status: status, p_rows: rows,
         p_detail: { ...detail, summary, trigger: $execution.mode, execution_id: $execution.id } },
} }];
